void ev_adv_timeout(u8 e, u8 *p, int n);
#include "scanning_under_test.c"
#include "ble_callbacks_under_test.c"

static void now(u32 utc) { wrk.utc_time_sec = hardware_utc = utc; }
static void reset(void) {
    memset(&scan, 0, sizeof(scan)); memset(&wrk, 0, sizeof(wrk));
    memset(&adv_buf, 0, sizeof(adv_buf)); memset(&blta, 0, sizeof(blta));
    rx_enabled = scan_starts = scan_extension = 0; ticks = 100;
    cfg.measure_interval = 4; scan_init();
}
static void start_listen(void) {
    scan_v3_poll(); assert(scan.v3_inflight && scan.enabled && !scan.start_tik);
    assert(sent_len == 22 && sent[0] == 21 && sent[1] == 0x16);
    assert(sent[2] == 0xd2 && sent[3] == 0xfc && sent[17] == SYNC_V3_ROLE_REQUEST);
    int starts = scan_starts;
    app_advertise_prepare_handler(NULL);
    assert(scan.enabled && sent_len == 22); /* request is not overwritten */
    user_init_deepRetn(); assert(scan_starts == starts); /* no early RX */
    blta.adv_duraton_en = 0; /* controller duration event */
    ev_adv_timeout(0,NULL,0);
    assert(rx_enabled && scan_extension && scan.start_tik && scan_starts == starts+1);
    assert(adv_enabled && adv_type == ADV_TYPE_CONNECTABLE_UNDIRECTED && sent_len == 0);
    assert(suspend_mask == SUSPEND_DISABLE);
    ev_adv_timeout(0,NULL,0); user_init_deepRetn();
    assert(scan_starts == starts+1); /* repeated callback does not reset window */
}
static void reply(u8 report[37], u32 utc) {
    const u8 prefix[19] = {2,1,3,1, 1,2,3,4,5,6, 25, 2,1,6, 21,0x16,0xd2,0xfc,0x40};
    memset(report,0,37); memcpy(report,prefix,sizeof(prefix));
    report[19] = 0; report[20] = 55; report[21] = 0x50;
    report[22] = (u8)utc; report[23] = (u8)(utc>>8); report[24] = (u8)(utc>>16); report[25] = (u8)(utc>>24);
    report[26] = 0x54; report[27] = 8; report[28] = 'T'; report[29] = 'S'; report[30] = 1; report[31] = 2;
    report[32] = 0xd4; report[33] = 0xc3; report[34] = 0xb2; report[35] = 0xa1; report[36] = 0x80;
}
static void receive(u8 *report, int size) { scanning_event_callback(HCI_FLAG_EVENT_BT_STD|HCI_EVT_LE_META,report,size); }
static void idle(void) { assert(!scan.enabled && !scan.start_tik && !scan.v3_inflight && !rx_enabled && !scan_extension); }

int main(void) {
    const u32 epoch = 1792882800U;
    u8 report[37];
    reset(); start_listen(); reply(report,epoch);
    receive(NULL,0);
    for(int n=0; n<37; ++n) { receive(report,n); assert(scan.v3_inflight && !scan.v3_has_ref); }
    const unsigned corrupt[] = {1,10,14,15,16,17,18,19,21,26,27,28,29,30,31,32};
    for(unsigned i=0; i<sizeof(corrupt)/sizeof(corrupt[0]); ++i) {
        u8 old=report[corrupt[i]]; report[corrupt[i]] = 0xff;
        receive(report,37); assert(scan.v3_inflight && rx_enabled); report[corrupt[i]]=old;
    }
    report[31]=1; receive(report,37); assert(scan.v3_inflight); report[31]=2;
    receive(report,37); idle();
    assert(scan.v3_has_ref && !scan.v3_has_drift && wrk.utc_time_sec == epoch);
    assert(scan.v3_next_sync_utc == epoch+86400 && wrk.utc_time_sec_tick == ticks);
    assert(adv_enabled && adv_type == ADV_TYPE_CONNECTABLE_UNDIRECTED && !sent_len);
    user_init_deepRetn(); scan_v3_poll(); idle(); assert(scan.v3_has_ref);
    receive(report,37); assert(scan.v3_next_sync_utc == epoch+86400);
    now(epoch+86400+5); start_listen(); reply(report,epoch+86400); receive(report,37); idle();
    assert(scan.v3_has_drift && scan.v3_drift_ppm_x100 == 5787);
    /* Reboot discards reference; slow clock sign and zero drift expand correctly. */
    for(int error=-5; error<=0; error+=5) {
        reset(); now(epoch); start_listen(); reply(report,epoch); receive(report,37);
        now(epoch+86400+error); scan.v3_next_sync_utc=0; start_listen();
        reply(report,epoch+86400); receive(report,37); idle();
        assert(scan.v3_drift_ppm_x100 == (error ? -5787 : 0));
        if(!error) assert(scan.v3_next_sync_utc == epoch+86400+15*86400);
    }
    /* Invalid long/backwards/manual samples cannot become frequency estimates. */
    now(epoch+100000); scan.v3_next_sync_utc=0; start_listen();
    reply(report,epoch-1); receive(report,37); assert(!scan.v3_has_drift);
    scan_v3_clock_changed(); assert(!scan.v3_has_ref && !scan.v3_next_sync_utc);
    /* Even at the minimum interval, two short samples continue learning. */
    reset(); now(epoch); start_listen(); reply(report,epoch); receive(report,37);
    scan.v3_has_drift=1; scan.v3_drift_ppm_x100=200000;
    for(int i=1; i<=2; ++i) {
        now(epoch+i*21600+2); scan.v3_next_sync_utc=0; start_listen();
        reply(report,epoch+i*21600); receive(report,37);
    }
    assert(scan.v3_drift_ppm_x100 == sync_v3_smooth_x100(200000,9259));
    assert(!scan.v3_sample_elapsed && !scan.v3_sample_error);
    /* Production scheduling regression for the review's drift sign reversal. */
    reset(); now(epoch); start_listen(); reply(report,epoch); receive(report,37);
    scan.v3_has_drift=1; scan.v3_drift_ppm_x100=4000;
    const u32 elapsed = sync_v3_interval_sec(4000);
    const u32 server = epoch+elapsed;
    now(server-69); scan.v3_next_sync_utc=0; start_listen();
    reply(report,server); receive(report,37); idle();
    assert(scan.v3_drift_ppm_x100 == 10 && scan.v3_last_sample_ppm_x100 == -11960);
    assert(scan.v3_next_sync_utc-server == sync_v3_interval_sec(-11960));
    assert(scan.v3_next_sync_utc-server < 3U*86400U);
    /* A short correction must retain the last complete measurement. */
    now(server+21600); scan.v3_next_sync_utc=0; start_listen();
    reply(report,server+21600); receive(report,37);
    assert(scan.v3_last_sample_ppm_x100 == -11960);
    assert(scan.v3_next_sync_utc-wrk.utc_time_sec == sync_v3_interval_sec(-11960));
    scan_v3_clock_changed(); assert(!scan.v3_last_sample_ppm_x100);
    /* Fixed window, hourly bootstrap, daily failure after a reference. */
    for(int ref=0; ref<=1; ++ref) {
        reset(); now(epoch); scan.v3_has_ref=ref; start_listen();
        ticks=scan.start_tik+2500U*16000U-1; scan_task(); assert(rx_enabled);
        ticks++; scan_task(); idle();
        assert(scan.v3_next_sync_utc == epoch+(ref ? 86400U : 3600U));
        assert(suspend_mask != SUSPEND_DISABLE);
        /* GATT interrupts and leaves the same retry policy. */
        scan.v3_next_sync_utc=0; start_listen(); ble_connect_callback(0,NULL,0); idle();
        assert(wrk.ble_connected && scan.v3_next_sync_utc == epoch+(ref ? 86400U : 3600U));
    }
    reset(); ticks=UINT32_MAX-80000000U; scan_v3_poll();
    ticks += 160000000U; now(0); scan_v3_poll(); idle();
    assert(scan.v3_next_sync_utc == 3600U && !blta.adv_duraton_en);
    reset(); adv_buf.ext_adv_init=1; scan_v3_poll(); assert(!scan.v3_inflight);
    adv_buf.ext_adv_init=0; wrk.ble_connected=1; scan_v3_poll(); assert(!scan.v3_inflight);
    printf("sync_v3 production radio callbacks (hard_clock=%d): OK\n",TEST_HARD_CLOCK);
    return 0;
}
